enum class Kind { Circle, Rect, Triangle };
struct Shape { Kind kind; union { Circle c; Rect r; Triangle t; } u; };

double area(const Shape& s) {
    switch (s.kind) {                 // -Wswitch-enum reports a new tag
    case Kind::Circle:   return 3.14159265358979 * s.u.c.r * s.u.c.r;
    case Kind::Rect:     return s.u.r.w * s.u.r.h;
    case Kind::Triangle: return 0.5 * s.u.t.base * s.u.t.h;
    }
    std::abort();                     // unreachable when coverage is complete
}
